import{_ as c,C as l,o as n,c as p,a2 as s,b as o,w as t,a as d,E as r,a3 as i}from"./chunks/framework.CZqXuAiL.js";const A=JSON.parse(`{"title":"Architecture Overview","description":"Sentinel's system architecture — components, the detection-to-suspension event pipeline, database schema, versioned config push/reconcile, and failure modes.","frontmatter":{"title":"Architecture Overview","description":"Sentinel's system architecture — components, the detection-to-suspension event pipeline, database schema, versioned config push/reconcile, and failure modes."},"headers":[],"relativePath":"pterodactyl-sentinel/architecture/overview.md","filePath":"pterodactyl-sentinel/architecture/overview.md","lastUpdated":1785525039000}`),h={name:"pterodactyl-sentinel/architecture/overview.md"};function u(g,e,v,m,_,f){const a=l("Mermaid");return n(),p("div",null,[e[2]||(e[2]=s(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Sentinel is two components speaking one contract:</p><ul><li><strong>Panel addon</strong> (PHP 8.2+/Laravel, Blueprint id <code>pterodactylsentinel</code>) — the brain. Owns all state, all secrets, the admin UI, enforcement policy, threat intel, and the versioned config.</li><li><strong>Node agent</strong> (Go 1.22+, single static CGO-free binary <code>sentinel</code>) — the sensor/enforcer. One per Wings node. Detects, executes local containment, and reports. Holds exactly one secret: its pairing token.</li></ul><p>The binding design rule: <strong>the panel is the brain, the node is the sensor/enforcer.</strong> No panel Application API key exists on any node — the old generation of node daemons embedded one, and that was explicitly rejected.</p><hr><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="panel-addon" tabindex="-1">Panel addon <a class="header-anchor" href="#panel-addon" aria-label="Permalink to &quot;Panel addon&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th></tr></thead><tbody><tr><td>Admin UI (8 tabs)</td><td>Dashboard, Detections, Nodes, Servers, Scans, Intel, Quarantine, Settings — AdminLTE, admin-only</td></tr><tr><td><code>routes/api-sentinel.php</code></td><td>Node-facing API with token auth, JSON validation, 120/min throttle</td></tr><tr><td><code>SentinelConfigService</code></td><td>Global config tree, per-node overrides, deep-merge, <code>config_version</code>, alert channels, YARA bundle</td></tr><tr><td>Intel service</td><td>Hash upserts, confirm-threshold tracking, distribution payload (<code>hashes</code> + <code>yara_rules</code> with versions)</td></tr><tr><td>Enforcement</td><td>Panel-side <code>suspend_server</code> via <code>SuspensionService</code> when a matching rule fires on an incoming event</td></tr><tr><td>Alert dispatcher</td><td>Discord / webhook / SMTP with per-channel severity, cooldown, rate limit + batching</td></tr><tr><td><code>sentinel:housekeeping</code></td><td>Offline sweep (stale heartbeats) + event retention pruning</td></tr></tbody></table><h3 id="node-agent-packages-node-module-internal" tabindex="-1">Node agent packages (<code>node-module/internal/</code>) <a class="header-anchor" href="#node-agent-packages-node-module-internal" aria-label="Permalink to &quot;Node agent packages (\`node-module/internal/\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Role</th></tr></thead><tbody><tr><td><code>config</code></td><td>Schema, defaults, validation, atomic write (temp + rename), versioned panel overlay</td></tr><tr><td><code>system</code></td><td><code>/proc</code> snapshot: process walk, per-netns connection table, container ID from cgroup, socket→pid resolution with a worker pool and time budget</td></tr><tr><td><code>docker</code></td><td>Minimal unix-socket client (list/inspect/stats/top/logs/pause/stop/kill); one shared instance; 30 s container cache; container→server-UUID resolver</td></tr><tr><td><code>detectors</code></td><td>The 12 detectors — see <a href="./detectors">Detectors</a>. One shared snapshot per tick</td></tr><tr><td><code>engine</code></td><td>Tick loop, cooldown dedup, rule matching, action execution, event spool</td></tr><tr><td><code>actions</code></td><td>quarantine/delete/kill-process/pause/stop container; suspend is report-only node-side</td></tr><tr><td><code>panel</code></td><td>Pairing, 30 s heartbeat, event batch flush, scan result POST, intel submit, config pull/reconcile; bounded on-disk spool</td></tr><tr><td><code>api</code></td><td>HTTP API on <code>:8481</code> (bearer): status, stats, events, config push, scan trigger/poll, health</td></tr><tr><td><code>intel</code></td><td>YARA rules + hash blocklist management (panel-distributed + optional external feed), hot reload on sync</td></tr></tbody></table><h3 id="server-attribution" tabindex="-1">Server attribution <a class="header-anchor" href="#server-attribution" aria-label="Permalink to &quot;Server attribution&quot;">​</a></h3><p>Every event is server-attributed. Wings names each server container with the server UUID; the agent resolves the UUID once per container via (1) docker labels, (2) container name, (3) volume-bind path (<code>/var/lib/pterodactyl/volumes/&lt;uuid&gt;</code>), using the shared docker client/cache. Even file-path-only events (from on-access or volume scans) get stamped with a server UUID via the volume path. Non-matching containers are ignored for per-server features but still covered by host-level detectors.</p><hr><h2 id="event-pipeline" tabindex="-1">Event pipeline <a class="header-anchor" href="#event-pipeline" aria-label="Permalink to &quot;Event pipeline&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/proc + docker snapshot (one per tick)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   detectors (12) ── enabled? ──► skip</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> cooldown dedup (same detector+target suppressed</span></span>
<span class="line"><span> for general.cooldown_seconds)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> whitelist check (path prefix / muted server)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> rules engine: first (category, min_severity) match</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> local actions (unless dry_run):</span></span>
<span class="line"><span> alert · quarantine_file · delete_file · kill_process</span></span>
<span class="line"><span> · pause_container · stop_container</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> event spool (bounded on-disk WAL, ~10k cap)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> batch flush → POST /api/sentinel/node/events (≤200/call)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> panel: dedupe on uuid → store → flagged-server upsert</span></span>
<span class="line"><span> → panel-side enforcement (suspend_server) → alerts</span></span></code></pre></div><h3 id="detection-to-suspension" tabindex="-1">Detection to suspension <a class="header-anchor" href="#detection-to-suspension" aria-label="Permalink to &quot;Detection to suspension&quot;">​</a></h3>`,16)),(n(),o(i,null,{default:t(()=>[r(a,{id:"mermaid-201",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20Container%0A%20%20%20%20participant%20A%20as%20Node%20agent%0A%20%20%20%20participant%20P%20as%20Panel%20addon%0A%20%20%20%20participant%20D%20as%20Discord%2FSMTP%0A%20%20%20%20participant%20W%20as%20Wings%2FSuspensionService%0A%0A%20%20%20%20A-%3E%3EC%3A%20tick%3A%20snapshot%20%2Fproc%20%2B%20docker%0A%20%20%20%20A-%3E%3EA%3A%20miner%20detector%3A%20critical%20(stratum%20args)%0A%20%20%20%20A-%3E%3EA%3A%20cooldown%20dedup%20%E2%86%92%20rules%20match%20(miners-critical)%0A%20%20%20%20A-%3E%3EC%3A%20stop_container%20(local%20action)%0A%20%20%20%20A-%3E%3EA%3A%20spool%20event%0A%20%20%20%20A-%3E%3EP%3A%20POST%20%2Fevents%20%7B%20batch%20%7D%0A%20%20%20%20P-%3E%3EP%3A%20dedupe%20uuid%2C%20store%20event%2C%20upsert%20flagged%20server%0A%20%20%20%20P-%3E%3EW%3A%20SuspensionService%3A%20suspend%20server%20(panel-authoritative)%0A%20%20%20%20P-%3E%3ED%3A%20alert%20(severity%20%E2%89%A5%20channel%20min%2C%20cooldown%20%2B%20rate%20limit)%0A%20%20%20%20P--%3E%3EA%3A%20%7B%20accepted%3A%201%2C%20duplicates%3A%200%20%7D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<p>Key semantics:</p><ul><li><strong>Local actions are immediate</strong> and recorded in <code>actions_taken</code>; the event is shipped regardless of action outcome.</li><li><strong><code>suspend_server</code> is panel-side.</strong> The node never suspends; the panel does, idempotently, when the event arrives. Suspension is panel-authoritative and survives node restarts and node action failures.</li><li><strong><code>dry_run: true</code></strong> → no local actions, no panel suspension; the event carries <code>dry_run: true</code> and empty <code>actions_taken</code>.</li><li><strong>Muted servers</strong> suppress local actions AND alerts, but events are still recorded with <code>evidence.muted: true</code>.</li><li><strong>Idempotency everywhere.</strong> Events carry a node-generated UUID; the panel dedupes on a unique index, so retries and spool replays are safe.</li></ul><hr><h2 id="database-schema" tabindex="-1">Database schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to &quot;Database schema&quot;">​</a></h2><p>All tables are <code>sentinel_</code>-prefixed; FK columns are <code>unsignedInteger</code> to match Pterodactyl core tables.</p>',5)),(n(),o(i,null,{default:t(()=>[r(a,{id:"mermaid-239",class:"mermaid",graph:"erDiagram%0A%20%20%20%20NODES%20%7C%7C--o%7C%20sentinel_node_tokens%20%3A%20%22has%20token%22%0A%20%20%20%20NODES%20%7C%7C--o%7B%20sentinel_events%20%3A%20%22reports%22%0A%20%20%20%20SERVERS%20%7C%7C--o%7B%20sentinel_events%20%3A%20%22attributed%22%0A%20%20%20%20SERVERS%20%7C%7C--o%7C%20sentinel_flagged_servers%20%3A%20%22flagged%22%0A%20%20%20%20SERVERS%20%7C%7C--o%7B%20sentinel_scans%20%3A%20%22scanned%22%0A%20%20%20%20NODES%20%7C%7C--o%7B%20sentinel_scans%20%3A%20%22runs%22%0A%20%20%20%20SERVERS%20%7C%7C--o%7B%20sentinel_quarantines%20%3A%20%22quarantined%20files%22%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<ul><li><strong><code>sentinel_node_tokens</code></strong> — <code>node_id</code> (FK cascade), token hash (bcrypt) + encrypted copy + indexed 16-char <code>token_prefix</code>, <code>api_url</code>, <code>last_seen_at</code>, <code>agent_version</code>, <code>config_version</code>, <code>config_pushed_at</code>, status fields (<code>is_online</code>).</li><li><strong><code>sentinel_events</code></strong> — <code>uuid</code> (unique), <code>node_id</code>, <code>server_id</code> (nullable FK, nullOnDelete), <code>container_id</code>, <code>category</code>, <code>detector</code>, <code>severity</code>, <code>title</code>, <code>evidence</code> (json), <code>actions_taken</code> (json), <code>created_at</code>.</li><li><strong><code>sentinel_hashes</code></strong> — <code>hash</code> (unique), <code>file_name</code>, <code>detection_type</code>, <code>reports</code>, <code>node_ids</code> (json), <code>confirmed</code>, <code>source_server</code>, <code>first_seen_at</code>, <code>last_seen_at</code>.</li><li><strong><code>sentinel_flagged_servers</code></strong> — <code>server_id</code> (FK cascade), <code>times_flagged</code>, <code>detection_types</code> (json), <code>last_flagged_at</code>, <code>muted_until</code> (nullable).</li><li><strong><code>sentinel_scans</code></strong> — <code>node_id</code>, <code>server_id</code> (nullable), <code>type</code>, <code>status</code>, <code>stats</code> (json), <code>findings</code> (json), <code>triggered_by</code> (user id), started/finished timestamps.</li><li><strong><code>sentinel_quarantines</code></strong> — <code>node_id</code>, <code>server_id</code> (nullable), <code>original_path</code>, <code>quarantine_path</code>, <code>file_hash</code>, <code>status</code> (<code>quarantined|restored|deleted</code>), <code>event_uuid</code>, timestamps.</li><li><strong><code>sentinel_settings</code></strong> — <code>key</code> (unique), <code>value</code> (json). Holds the global config tree (<code>config</code>), <code>config_version</code>, per-node overrides (<code>node_config_override_&lt;id&gt;</code>), alert channels (<code>alerts</code>), and the YARA bundle (<code>yara_rules</code>).</li></ul><p>Events for deleted servers keep <code>server_id = null</code> rather than vanishing — the audit trail outlives the server.</p><hr><h2 id="config-versioning-push-and-reconcile" tabindex="-1">Config versioning, push and reconcile <a class="header-anchor" href="#config-versioning-push-and-reconcile" aria-label="Permalink to &quot;Config versioning, push and reconcile&quot;">​</a></h2><ol><li>Admin saves anything in Settings → <code>SentinelConfigService</code> validates and normalizes the tree (whitelisted keys, cast scalars, validated enums, one-per-line lists) and persists it, then <strong>bumps <code>config_version</code></strong> (monotonic).</li><li>The panel builds each node&#39;s <strong>effective config</strong> — per-node override deep-merged over the global tree (scalars/lists replace, maps recurse) — and pushes it to every online node: <code>POST /api/v1/config</code> with <code>{config_version, config, intel}</code>.</li><li>The node <strong>validates the whole tree</strong> (ranges, log levels, rule actions, categories) and rejects bad pushes outright. Valid configs are written to a temp file, atomically renamed, reloaded, and persisted as last-known-good.</li><li>Offline nodes are not lost: every heartbeat returns the panel&#39;s current <code>config_version</code>, and a stale node immediately does <code>GET /config</code> and applies. The heartbeat can also carry one-shot <code>commands</code> (<code>rescan_intel</code>, <code>push_config</code>) which the node executes and acks.</li><li>Re-applying the same version is a no-op success — pushes are safe to repeat.</li></ol><p>The intel payload rides the same channel: confirmed <code>hashes</code> (with <code>hashes_version</code>) and the <code>yara_rules</code> bundle (with <code>yara_version</code>), hot-reloaded by the agent&#39;s intel manager.</p><hr><h2 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Panel unreachable</strong></td><td>Node keeps detecting and enforcing with its last-known config. Events queue in the bounded on-disk spool (WAL, ~10k cap, oldest dropped past it) and flush in batches when the panel returns. Heartbeat/registration retry with backoff forever.</td></tr><tr><td><strong>Node unreachable</strong></td><td>Housekeeping marks it offline after <code>sentinel.offline_after_seconds</code> (default 120 s) without a heartbeat. The panel keeps its last data; config pushes resume on return.</td></tr><tr><td><strong>Bad config pushed</strong></td><td>Node-side validation rejects the entire tree before apply; the last-known-good config keeps running. A bad push can never take effect.</td></tr><tr><td><strong>Token reset / compromised</strong></td><td>Old token dies instantly (bcrypt verify fails on the next call). The node retries and stays offline until re-paired. No other credential exists on the node to leak.</td></tr><tr><td><strong>Detection storm</strong></td><td><code>limits.max_events_per_minute</code> (default 60) caps per-node event throughput; alert dispatch is rate-limited and batched panel-side.</td></tr><tr><td><strong>Agent crash</strong></td><td>systemd restarts it (<code>Restart=always</code>, max 5/60 s); persisted config, spool and quarantine state survive in <code>/var/lib/sentinel</code>.</td></tr><tr><td><strong>Cross-node event injection</strong></td><td>Events whose <code>server_uuid</code> does not belong to the authenticated node are stored with <code>server_id = null</code> — never silently dropped, never cross-attributed.</td></tr></tbody></table>',9))])}const k=c(h,[["render",u]]);export{A as __pageData,k as default};
